-- Figures live in public/q/may23/. Ids are fixed, so running this file again updates the test instead of copying it.

-- PeaklyTest May 2023 · Reading & Writing · Module 1
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('993466f7-35f4-524a-939c-bfe0d4f84270', 'PeaklyTest May 2023 · Reading & Writing · Module 1', 'Reading & Writing', 'Reading & Writing, Module 1 of the May 2023 PeaklyTest · 27 questions · 32 minutes', 32, 360, true, 'PeaklyTest May 2023 · Reading & Writing', 1)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('12b12330-85af-5274-aa4f-679d46f96736', '993466f7-35f4-524a-939c-bfe0d4f84270', 'As used in the text, what does the word "registered" most nearly mean?', '["enrolled", "valued", "disregarded", "displayed"]'::jsonb, 1, 'The following text is from John Matheus’s 1925 novel Fog . The story happens in a city where heavy fog has set in.

The little conductor stood on tiptoe in an effort to keep one hand on the signal rope, craning his neck in a vain and dissatisfied endeavor to pierce the miasma of the fog. The motorman chafed in his box, thinking of the drudging lot of the laboring man. He <u>registered</u> discontent.'),
  ('2129684b-be6e-5295-8e60-e75cee7925f1', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice completes the text with the most logical and phrase word or phrase?', '["diminish", "increase", "vary", "measure"]'::jsonb, 2, 'One way to _____ the importance of a scholar’s research is to track how often other scholars refer to that research. For example, Federal Reserve Bank of Cleveland economist Loretta J. Mester, who studies central banking, is among the world’s most frequently cited researchers in her field, indicating that her work has been quite significant.'),
  ('4a445d07-3ff3-5597-bd7d-efb3b0b36cd3', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice completes the text with the most logical and precise word or phrase?', '["irrelevant to", "prohibitive in", "distinctive to", "unchanging in"]'::jsonb, 3, 'Although fewer companies trade their stocks on the Tehran Stock Exchange in Tehran, Iran, than on the stock exchanges in London, Mumbai, or Tokyo, the Tehran Stock Exchange has the advantage of focusing on local companies and thus reflecting economic circumstances that are _____ Iran. This sensitivity to unique, rapidly evolving local conditions benefits the companies and investors alike.'),
  ('c271b376-07af-5a17-92ed-99ba7e32ba58', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice best describes the function of the underlined portion in the text as a whole?', '["It introduces a counterexample to the scenario described earlier in the text.", "It provides context to help understand the scope of the researchers'' survey.", "It marks a shift from a discussion of the researchers’ conclusion to a discussion of their methods.", "It presents a potential explanation for the team’s findings that the text goes on to refute."]'::jsonb, 4, 'In a study by Mika R. Moran, Daniel A. Rodriguez, and colleagues, residents of Caracas, Venezuela, and of Fortaleza, Brazil, were surveyed about parks in their cities. Of the 1,043 respondents from Caracas, 44.7% indicated that they use the city’s parks, and of the 938 respondents from Fortaleza, 35.7% indicated using city parks. <u>It may be tempting to assume the difference is due to different levels of</u> <u>access to parks</u>; however, given that the percentage of Caracas respondents who reported living within a 10-minute walk of a park was much lower than that reported by Fortaleza respondents, greater proximity alone can’t explain the difference in park use.'),
  ('39d72654-e07d-5daf-a0f3-3b84da467c54', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which quotation from Uncle Vanya most effectively illustrates the claim?', '["Professor Serebrakoff says, \"I am a book-worm and a scholar, and am unfamiliar with practical affairs. I cannot, I find, dispense with the help of well-informed people.\"", "Professor Serebrakoff says to Helena, \"My darling, don’t leave me alone with [Vanya]. He will begin lecture me.\"", "Professor Serebrakoff says to Helena, \"I am used to my library and the lecture hall and to the esteem and admiration of my colleagues. Now I suddenly find myself plunged into this wilderness (the cottage), condemned to see the same stupid people from morning till night and listen to their futile conversations.\"", "Vanya says to Professor Serebrakoff, \"You write on art without knowing anything about it. Those books of yours which I used to admire are not worth one copper kopeck. You are a hoax!\""]'::jsonb, 5, 'The following text is adapted from Anton Chekhov’s 1899 play Uncle Vanya. Professor Serebrakoff retires and moves to his country estate, which Vanya manages with the help of Sonia, the professor’s daughter from a previous marriage. Chekhov portrays the professor as being someone unable to adjust to living at the country estate, as is evident when _____'),
  ('c4313be6-34be-5b6d-8697-7cb0fe12e779', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice best states the main purpose of the text?', '["To indicate that crowded areas can cause people to feel as though they are children again.", "To caution people not to be so quick to dismiss the natural beauty that can be found in rural areas.", "To address common traits that motivates many people to choose to live in urban environments.", "To illustrate the idea that most people tend to prefer hillsides in the country to certain aspects of towns and cities."]'::jsonb, 6, 'The following text is from Jerome K. Jerome’s 1889 novel Three Men in a Boat.

We are creatures of the sun, we men and women. We love light and life. That is why we crowd into the towns and cities, and the country grows more and more deserted every year. In the sunlight—in the daytime, when Nature is alive and busy all around us, we like the open hillsides and the deep woods well enough: but in the night, when our Mother Earth has gone to sleep, and left us waking, oh! the world seems so lonesome, and we get frightened, like children in a silent house. Then we sit and sob, and long for the gas-lit streets, and the sound of human voices, and the answering throb of human life.'),
  ('01d5602a-20ad-5952-a13b-f0edd8353888', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice best describes the main idea of the text?', '["Cuttlefish eyes are much more complex than those of falcons or horses.", "Wardill’s team designed 3D glasses for cuttlefish.", "Before completing their study, Wardill’s team thought that cuttlefish have 3D vision, but horses may not.", "The finding of Wardill’s team’s study suggests like falcons and horses, cuttlefish may also have 3D vision."]'::jsonb, 7, 'Falcons and horses can see in three dimensions (3D), which helps them perceive distance and depth. Octopuses and squid are thought to lack 3D vision. Many researchers once thought the same about cuttlefish, but Trevor Wardill and his team wanted to test whether this assumption was true. The team studied how cuttlefish wearing 3D glasses reacted to 3D images of shrimp (a favorite prey) projected on a tank wall. Cuttlefish changed their striking position to match the 3D images, suggesting that their vision is more like that of falcons and horses than that of octopuses or squid.'),
  ('f58635ce-95f5-5af9-85d6-63bac477d316', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice best states the main idea of the text?', '["Chuck Colson and John Dean were significant figures in the presidency of Richard Nixon.", "Richard Nixon is commonly linked with an infamous historical event, but this overshadows some of his notable achievements.", "Some of Richard Nixon’s policies influenced the policies of later presidential administrations.", "Richard Nixon’s reputation is primarily due to the actions of his associates."]'::jsonb, 8, 'President Richard Nixon is most famous for his participation in the 1970s Watergate political scandal, a convoluted tale of criminality and eroded ethics involving a constellation of associates such as White House Counsel Chuck Colson and White House Counsel John Dean. But Nixon’s legacy is complex: he has been praised for his role in creating the Environmental Protection Agency, and he once made an attempt at reforming United States health care policy that is arguably a precursor to the Affordable Care Act, which became law during the Barack Obama administration.'),
  ('a279d7fd-3def-59ca-98fe-8ff2a47831ab', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which quotation from Cane most effectively illustrates the claim?', '["“The [train] engines of this valley have a whistle, the echoes of which sound like iterated gasps and sobs. I always think of them as crude music.”", "“And when the wind is from the South, soil of my homeland falls like a fertile shower upon the lean streets of [Washington, DC].”", "“I sang, with a strange quiver in my voice, a promise-song.”", "“The young trees had not outgrown their boxes then. V Street [in Washington, DC] was lined with them.”"]'::jsonb, 9, 'Cane is a 1923 novel by Jean Toomer. In one portion of the novel, Toomer uses figurative language to connect the narrator’s urban environment of Washington, DC, and the rural South of the narrator’s past, writing _____'),
  ('4d4272bd-5122-5909-b5be-8323281d340e', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which finding, if true, would most directly support Bainbridge and colleagues claim?', '["The heart rates of infants in the study were more irregular during the lullabies than during non-lullabies.", "Parents of infants in the study chose the lullaby over the non-lullaby when asked which song they Infants'' use to calm their child.", "Infants’ heart rates were substantially lower during the lullaby than during the non-lullaby.", "Both the song in Western Nahuatl and the song in Serbian were sung by a female singer."]'::jsonb, 10, 'Many believe that lullabies, characterized by their less steady beat, contain some acoustic features that are universally calming to infants. In a study, Constance M. Bainbridge and colleagues played both a lullaby sung in the Western Nahuatl language and a non-lullaby sung in the Serbian language to a group of infants. The researchers also measured the infants'' heart rates, as a reduced heart rate is considered a measure of relaxation. They claim that the lullaby did indeed relax the infants.'),
  ('fa54db24-c3a3-5948-83a3-efd1ba3ee65d', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice uses data from the table to most effectively complete the comparison?', '["surpassed the contribution made by administration/waste but fell short of that made by real estate.", "exceeded the contribution made by both administration/waste and real estate.", "was greater than the contribution made by real estate but equal to that made by administration/waste.", "was lower than the contribution made by either administration/waste or real estate."]'::jsonb, 11, '**Contributions of Three Key Industries to Oklahoma Economy in 2017**

| Industry | Approximate contribution |
| Real estate | \$ 18,314,700,000 |
| Tribal economic activity | \$ 7,312,400,000 |
| Administration/waste | \$ 5,830,600,000 |

The Cherokee Nation, the Seminole Nation, and the more than thirty other tribes in Oklahoma operate numerous businesses and collectively generate billions of dollars in revenue. In fact, when the tribes'' economic activity is regarded as a single industry, its contribution to the Oklahoma economy in 2017 _____'),
  ('89b41fe8-ac43-57f5-b5f7-3b6c4c25161f', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which finding, if true, would most directly support the second research team’s hypothesis?', '["A study using obstructions that created large vortices in low-visibility conditions found that the narrow-headed lake sturgeon ( Acipenser fulvescens ) bumped into obstructions more often than the intermediate-headed dusky smooth-hound ( Mustelus canis ) did.", "A study using obstructions that created large vortices in low-visibility conditions found that the lake sturgeon (Acipenser fulvescens), which has a relatively narrow head, bumped into more than half of the obstructions.", "A study using obstructions that created large vortices in low-visibility conditions found that some specimens of the intermediate-headed dusky smooth-hound (Mustelus canis) bumped into the obstructions more often than other specimens of the same fish did.", "A study using obstructions that created large vortices in low-visibility conditions found that the intermediate-headed dusky smooth-hound (Mustelus canis) avoided more than half of the obstructions."]'::jsonb, 12, 'Water flowing around an obstruction creates vortices (patterns of swirls) of varying size; by detecting the vortices, fish can determine the size and position of the obstruction. Testing by Yuzo R. Yanagisuru, Otar Akanyeti, and James C. Liao using models of three head shapes—narrow (low ratio of width to length), intermediate, and wide (high ratio of width to length)—showed that for large vortices, fish with intermediate heads would be better able than narrow-headed fish to distinguish between vortices and general turbulence in the water. A second research team has therefore hypothesized that in low-visibility conditions, intermediate-headed fish will be more likely than narrow-headed fish to detect obstructions that create large vortices.'),
  ('bef9bc38-4259-5b95-bd36-f759dec9f1ee', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice best describes data from the graph that support the student’s claim?', '["In at least one of the four urban areas shown, the amount of traffic delay was less than 20 hours per commuter per year at one point between 1990 and 2000.", "While the annual number of hours of traffic delay per commuter was always lower in the Boise, Idaho, area than in the New York City, New York, area for each year between 1990 and 2000, the amount of traffic delay rose in both areas during this period.", "Even though the amount of traffic delay per commuter per year was greater in the Albuquerque, New Mexico, area than in the New York City, New York, area throughout the period from 1990 to 2000, the amounts were nearly identical in 1996.", "In 1992, the amount of traffic delay in the New York City, New York, area was less than 30 hours per commuter per year."]'::jsonb, 13, '![figure](/q/may23/001.webp)

In a college course on urban affairs, a student asserts that increased traffic congestion in the 1990s in the United States was present both in very large cities such as New York City, New York, and smaller areas such as Albuquerque, New Mexico, Jacksonville, Florida, and Boise, Idaho; though those smaller areas may have been less affected by traffic congestion than very large cities, this congestion also worsened in them over time.'),
  ('106524e5-94c8-569f-b3d3-6431a5b21e03', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice best describes data in the table that support the city planner’s conclusion?', '["The improvement of physical health was ranked lower for the general public than it was for project leaders.", "The provision of raw materials was ranked higher for the general public than was the improvement of attitudes and outlooks.", "The improvement of attitudes and outlooks was ranked higher for stakeholders than it was for the general public.", "The improvement of attitudes and outlooks was ranked higher for the general public than were the other four services."]'::jsonb, 14, '**Ranking of Environmental and Sociocultural Benefits of Urban Agriculture (scale of 1 to 25;** **1=highest)**

| Social or ecological service | Project leaders | Stakeholders | General public |
| improvement of attitudes and outlooks | 8 | 1 | 4 |
| provision of food | 4 | 15 | 8 |
| provision of raw materials | 22 | 25 | 15 |
| improvement of physical health | 5 | 4 | 7 |
| enhancement of pollination | 1 | 7 | 12 |

Esther Sanye-Mengual, Kathrin Specht, and their team surveyed three groups of people in Bologna, Italy —leaders of urban agriculture projects, stakeholders in urban agriculture (e. g., food researchers and urban farming associations), and the general public—to compare their views about the extent to which urban agriculture contributes to 25 social or ecological services that the team identified. The researchers used these ratings to rank the services for each group, with a conclusion that both stakeholders and general public regard the improvement of attitudes and outlooks as important benefit of urban agriculture.'),
  ('4aaa0bc9-d10f-53ed-a386-60e284277e62', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice most logically completes the text?', '["On Oahu, the rate of population increase is higher for non-native plants than it is for vulnerable native forest plants, like lapalapa trees.", "Night-blooming jessamine shrubs and other non-native forest plants only recently began to outnumber native forest plants in the wild.", "On Oahu, native plants, such as the lapalapa tree, are already growing in most of the spots where red-whiskered bulbuls would be likely to drop plant seeds on Oahu.", "The lapalapa tree and the night-blooming jessamine shrub are the plant species most in danger of going extinct in the wild."]'::jsonb, 15, 'Like many other fruit-eating birds on the Hawaiian island of Oahu, the red-whiskered bulbul helps forest plants spread by dropping seeds from the plants'' fruits in different spots (a process called seed dispersal). Ecologists have found that fruit-eating birds disperse some seeds from native plants at risk of extinction in the wild, such as the lapalapa tree. However, the birds disperse a higher number of seeds from nightblooming jessamine shrubs and other non-native plants with large populations, likely because there are so many more of those plants for them to choose from. Therefore, it isn’t surprising that _____'),
  ('37e89a1b-8016-5028-8624-7795700aa659', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["wastes;", "wastes and to", "wastes,", "wastes"]'::jsonb, 16, 'Cut, bent, and welded from discarded metal materials, the sculptures of London-based Nigerian artist Sokari Douglas Camp are meant to challenge viewers to consider their own relationships to material _____ her thought provoking works in the 1993 exhibition Steel Clothes and Ornamentation at the Redfern Gallery in London were no different.'),
  ('bb30c107-f5a2-5b06-987a-a38a9aa484b4', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["the result of chemist Ahmed Zewail’s expansion of the limits of measurability was the introduction of a new scientific discipline", "the introduction of a new scientific discipline by chemist Ahmed Zewail led to the expansion of the limits of measurability", "the limits of measurability were expanded by chemist Ahmed Zewail who introduced a new scientific discipline", "chemist Ahmed Zewail expanded the limits of measurability and introduced a new scientific discipline"]'::jsonb, 17, 'A recipient of the Othmer Gold Medal and the Davy Medal from the Royal Society, _____ known as femtochemistry when he devised an optical spectroscopy technique that allowed researchers to study ultrafast chemical reactions occurring within molecules.'),
  ('04d442af-04cd-575e-8a3a-701d8a734a63', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["flow", "flows", "have flowed", "are flowing"]'::jsonb, 18, 'The Amur River, which is 2,714 miles long, _____ into the Sea of Okhotsk.'),
  ('014bb843-9223-504b-94cf-847ecc5e2ac1', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["it was invented by an author.", "it was invented by an author?", "wasn’t it invented by an author.", "was it invented by an author."]'::jsonb, 19, 'What is the origin of the word “pessimism”? Interestingly, _____ It first appears in a letter by English author Samuel Taylor Coleridge.'),
  ('e2cd0333-0723-5aac-beee-e48aa6de0a6f', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["you", "it", "anyone", "they"]'::jsonb, 20, 'After much debate, _____ finally made a decision: the judges for the 1974 Nobel Prize in Literature would award Eyvind Johnson of Sweden with that year’s prize “for a narrative art, far-seeing in lands and ages, in the service of freedom.”'),
  ('e591ea4a-9ec4-535b-a045-73bce48bef6b', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["drive.", "drive", "drive:", "drive;"]'::jsonb, 21, 'Today, the Michelin Guide is widely known as the arbiter of fine dining, with its coveted 3-star rating being awarded to top restaurants like Xin Rong Ji in Beijing. However, few know the guide started as a marketing gimmick in 1900, when brothers Andre and Edouard Michelin sought to increase profits for their tire company by encouraging their customers to _____ their cars across France, visiting the guide’s recommended hotels and restaurants along the way.'),
  ('b350eb2f-2105-51cb-8f7c-694dd91508de', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["appearing", "appears", "has appeared", "appeared"]'::jsonb, 22, 'Pinon Chapter is one of the 110 chapters of the Navajo Nation (Naabeeho Bincihdsdzo). The chapter, known as Be''ek''id Bas Ahoodzdni in the Navajo language (Dine Bizaad), was the subject of a profile _____ in the Navajo Times on December 12, 2013.'),
  ('e6edce32-d100-590e-8bbb-3993fa1c49c2', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["known", "known:", "known—", "known;"]'::jsonb, 23, 'Writer Silvia Moreno-Garcia’s love of short fiction began when she read a collection of Edgar Allan Poe stories as a child, and she later would become a prolific short story writer herself, publishing pieces like “In the Details” (2015) and “To See Pedro Infante” (2014). Yet she’s best _____ especially since her 2020 novel Mexican Gothic reached the New York Times Best Sellers list—as a novelist.'),
  ('da850e80-0f10-57e7-93d5-76abfbc61edb', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice completes the text with the most logical transition?', '["For example,", "Eventually,", "In other words,", "Earlier,"]'::jsonb, 24, 'In 1931, scientists first isolated a sample of the steroid hormone androsterone, which they knew existed in animals—and, they assumed, only in animals. _____ researchers would find androsterone in Swiss cheese plants (Monstera deliciosa), but this discovery wouldn’t come until decades later.'),
  ('bdb45cbd-84bb-569b-9705-9ef07c490ee0', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice completes the text with the most logical transition?', '["as a result,", "similarly,", "rather,", "finally,"]'::jsonb, 25, 'The first documented use of the English word “muzzle” is attributed to poet Geoffrey Chaucer’s 1385 work The Knight’s Tale. However, Chaucer didn’t write in Modern English; _____ he wrote in what we now call Middle English, which was commonly used during the period.'),
  ('19d6b62a-be74-563b-b44e-f8a40495189b', '993466f7-35f4-524a-939c-bfe0d4f84270', 'Which choice most effectively uses information from the given sentences to emphasize how the two works are similar?', '["Composed by artist Jean-Michel Basquiat in 1986 and 1987, respectively, both Thin in the Old and Victor use acrylic paint as a medium.", "Artist Jean-Michel Basquiat completed Thin in the Old in 1986, and Victor followed in 1987.", "Artist Jean-Michel Basquiat’s work Thin in the Old is composed of acrylic, oil, and paper collage, while Victor is composed of acrylic, oil stick, and crayon.", "Between artist Jean-Michel Basquiat’s works Victor and Thin in the Old, the former is the larger of the two."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Jean-Michel Basquiat was an American artist who produced more than two thousand drawings and paintings.
His work Thin in the Old was completed in 1986 and sold at auction in 2020.
Thin in the Old is composed of acrylic, oil, and paper collage on wood and measures 3,028 square inches in area.
His work Victor was completed in 1987 and sold at auction in 2017.
Victor is composed of acrylic, oil stick, and crayon on canvas and measures 9,432 square inches in area.'),
  ('b685a9c3-92b7-5524-a691-b2f759e869b7', '993466f7-35f4-524a-939c-bfe0d4f84270', 'The student wants to compare the hardness of talc and topaz. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Topaz can leave visible scratches on fluorite, which is why topaz has a higher number than fluorite on the Mohs scale of mineral hardness.", "The Mohs scale of mineral hardness can be used to order fluorite, talc, and topaz by their ability to scratch other minerals.", "A mineral with a Mohs number of 4, like fluorite, is harder than one with a Mohs number of 1, like talc.", "Topaz can leave visible scratches on talc, which means that topaz is harder than talc."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

The Mohs scale of mineral hardness is a ten-point scale that orders minerals by hardness based on their ability to scratch other minerals.
Minerals with larger numbers are harder than minerals with smaller numbers and can leave visible scratches on them.
Minerals with smaller numbers are softer than minerals with larger numbers and cannot leave visible scratches on them.
The mineral talc has a Mohs scale number of 1.
The mineral fluorite has a Mohs scale number of 4.
The mineral topaz has a Mohs scale number of 8.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('12b12330-85af-5274-aa4f-679d46f96736', 3, null, '**Choice D is correct.** In the context “He registered discontent,” registered means he showed or made his discontent known. The surrounding phrasing — the motorman chafed in his box, thinking of the drudging lot of the laboring man — indicates an active feeling being made evident, so “displayed” matches that sense.
**Choice A is incorrect.** “Enrolled” refers to signing up or being entered on a list, which doesn’t fit the emotional expression described.
**Choice B is incorrect.** “Valued” means judged important or given worth, which is unrelated to expressing discontent.
**Choice C is incorrect.** “Disregarded” means ignored; the sentence implies the motorman felt and showed discontent, not that he ignored it.
**Faster approach:** Substitute each choice into the phrase “He ___ discontent” and choose the word that preserves the sense of making an emotion evident — instantly eliminates meanings like enrolled or disregarded.'),
  ('2129684b-be6e-5295-8e60-e75cee7925f1', 3, null, '**Choice D is correct.** The sentence describes a method for determining the importance of a scholar’s research: tracking citations. The verb "measure" appropriately conveys determining or assessing degree, so "One way to measure the importance... is to track how often..." fits both grammatically and logically.
**Choice A is incorrect.** "Diminish" means to make smaller; tracking citations does not make the importance smaller, so it does not fit the intended meaning.
**Choice B is incorrect.** "Increase" means to make greater; tracking citations does not increase importance—it only assesses it—so this choice is illogical here.
**Choice C is incorrect.** "Vary" means to change or differ; the structure "One way to vary the importance... is to..." is ungrammatical and semantically wrong because the sentence intends assessment, not change.
**Faster approach:** Substitute each choice into the sentence and choose the one that yields a grammatically and semantically sensible result; for assessment contexts, "measure" is the typical collocation.'),
  ('4a445d07-3ff3-5597-bd7d-efb3b0b36cd3', 2, null, '**Choice C is correct.** The passage says the Tehran Stock Exchange focuses on local companies and therefore reflects economic circumstances that are specific to that country; "distinctive to" precisely conveys that those circumstances are characteristic of Iran. The following clause, "This sensitivity to unique, rapidly evolving local conditions," reinforces that the circumstances are particular to Iran rather than general or unchanging.
**Choice A is incorrect.** "Irrelevant to" means not related to Iran, which contradicts the passage’s claim that the exchange reflects local economic conditions.
**Choice B is incorrect.** "Prohibitive in" describes something that prevents action (e.g., costs), which does not fit the idea of reflecting economic circumstances.
**Choice D is incorrect.** "Unchanging in" conflicts with the passage’s description of "rapidly evolving local conditions," so it is the opposite of what the context requires.
**Faster approach:** Look for a word that matches the context clues—"local," "unique," and "rapidly evolving"—and eliminate choices with opposite or unrelated meanings; choose the word meaning "specific to the place."'),
  ('c271b376-07af-5a17-92ed-99ba7e32ba58', 3, null, '**Choice D is correct.** The underlined sentence proposes a plausible reason for the observed difference in park use—different levels of access—and the following clause (beginning with "however") explicitly rejects that explanation by pointing out that Caracas respondents reported lower proximity yet higher use. Thus the sentence introduces a potential explanation that the passage then refutes.
**Choice A is incorrect.** The underlined sentence does not give a counterexample; it suggests an explanation that is subsequently discarded rather than presenting specific contradictory data.
**Choice B is incorrect.** The sentence does not provide survey scope or context (such as sample size or location); it offers a hypothesis about why park use might differ.
**Choice C is incorrect.** The sentence does not signal a shift from conclusions to methods; it posits an explanatory idea that the text immediately evaluates.
**Faster approach:** Look for signal words ("may be tempting," "however")—if a claim is immediately followed by a rebuttal, the prior clause is a proposed explanation later refuted.'),
  ('39d72654-e07d-5daf-a0f3-3b84da467c54', 2, null, '**Choice C is correct.** This quotation directly states the professor’s inability to adjust: he contrasts his accustomed life of the library and lecture hall and then says he is "suddenly... plunged into this wilderness (the cottage), condemned to see the same stupid people"—language that explicitly expresses discomfort and alienation at the country estate.
**Choice A is incorrect.** Although it shows the professor is "unfamiliar with practical affairs," it focuses on needing help rather than explicitly describing his emotional or social discomfort at the country estate.
**Choice B is incorrect.** This remark is a request not to be left alone because Vanya would lecture him; it implies annoyance but does not illustrate the professor’s difficulty adjusting to estate life.
**Choice D is incorrect.** Vanya’s insult attacks the professor’s competence as an artist/scholar, but it does not demonstrate the professor’s own sense of being unable to adapt to living at the country estate.
**Faster approach:** Scan the quotations for one that explicitly expresses the claim (words like "plunged," "condemned," or direct comparisons to former life); the most direct statement of discomfort is the correct choice.'),
  ('c4313be6-34be-5b6d-8697-7cb0fe12e779', 2, null, '**Choice C is correct.** The passage explains why people prefer towns and cities: "We are creatures of the sun... That is why we crowd into the towns and cities," and it contrasts daytime enjoyment of nature with nighttime fear that drives people back to the "gas-lit streets" and "human voices." The paragraph presents general traits and motivations that make urban living attractive, which matches choice C.
**Choice A is incorrect.** The passage does not claim that crowded areas cause people to feel like children again; rather it compares adults’ nighttime fear in the country to children’s fear in a silent house, using that simile to explain why people return to towns.
**Choice B is incorrect.** The passage does not offer a caution about dismissing rural beauty; it acknowledges enjoyment of hillsides and woods by day but focuses on reasons people prefer cities overall.
**Choice D is incorrect.** While the passage notes a daytime preference for hillsides, its main point is that nighttime loneliness drives people to cities, so it does not assert a general preference for country hillsides over aspects of towns.
**Faster approach:** Read the topic sentence(s) that state the author’s main idea and then check which choice restates that idea broadly—here, the opening lines identify the central reason people choose urban life.'),
  ('01d5602a-20ad-5952-a13b-f0edd8353888', 3, null, '**Choice D is correct.** The passage reports that cuttlefish wearing 3D glasses adjusted their striking position to match 3D shrimp images, and it explicitly concludes that their vision is “more like that of falcons and horses.” That summary—that the study suggests cuttlefish may have 3D vision like falcons and horses—captures the main idea.
**Choice A is incorrect.** The passage does not claim that cuttlefish eyes are more complex than those of falcons or horses; it only compares the presence of 3D vision, not complexity of eyes.
**Choice B is incorrect.** Although the passage mentions cuttlefish wearing 3D glasses, the main idea is the study’s finding about 3D vision, not simply the design of the glasses.
**Choice C is incorrect.** The passage says researchers once thought cuttlefish lacked 3D vision, and Wardill’s study challenged that. It does not say Wardill’s team believed cuttlefish had 3D vision before the study or that horses might not have 3D vision.
**Faster approach:** Look for the sentence that states the study’s conclusion and choose the answer that restates that conclusion in your own words.'),
  ('f58635ce-95f5-5af9-85d6-63bac477d316', 1, null, '**Choice B is correct.** The passage contrasts Nixon’s widespread association with the Watergate scandal with other accomplishments—creating the Environmental Protection Agency and proposing health-care reform that anticipated the Affordable Care Act—so the main idea is that his infamous reputation overshadows important achievements.
**Choice A is incorrect.** While Chuck Colson and John Dean are named, the passage mentions them only to describe the Watergate context, not to claim they were the central focus.
**Choice C is incorrect.** The passage does note that one of Nixon’s proposals was a precursor to later policy, but that detail supports a broader point about his complex legacy rather than serving as the main idea itself.
**Choice D is incorrect.** The passage attributes Nixon’s reputation primarily to Watergate, not to actions of his associates; the associates are mentioned as part of that scandal, not as the primary cause of his reputation.
**Faster approach:** Identify the contrast word or phrase that signals the main idea (here, the contrast between fame for Watergate and noted achievements) and choose the answer that captures that contrast broadly rather than a narrow detail.'),
  ('a279d7fd-3def-59ca-98fe-8ff2a47831ab', 1, null, '**Choice B is correct.** The quotation explicitly links Washington, DC ("the lean streets of [Washington, DC]") with the narrator’s rural homeland ("soil of my homeland") using figurative language (soil "falls like a fertile shower") to blend the two settings and show how memories of the South figuratively cover the urban environment.
**Choice A is incorrect.** Although it uses figurative language to describe train engines as "crude music," it does not connect the urban scene to the rural South or the narrator’s past.
**Choice C is incorrect.** "I sang, with a strange quiver in my voice, a promise-song" conveys emotion or voice but offers no figurative link between city and rural homeland.
**Choice D is incorrect.** The image of young trees in boxes evokes urban planting but does not figuratively connect Washington to the rural South or the narrator’s memories.
**Faster approach:** Scan each quotation for explicit references to both settings and for figurative language; the correct choice will name both places and use a metaphor or simile to connect them.'),
  ('4d4272bd-5122-5909-b5be-8323281d340e', 2, null, '**Choice C is correct.** The researchers’ claim is that the lullaby relaxed infants, and the passage states that a reduced heart rate is considered a measure of relaxation. If infants’ heart rates were substantially lower during the lullaby than during the non-lullaby, that finding directly demonstrates the physiological evidence of relaxation the authors used, so it most directly supports the claim.
**Choice A is incorrect.** Greater irregularity of heart rates does not directly indicate relaxation; in fact, it could indicate arousal or instability rather than a reduced heart rate linked to relaxation.
**Choice B is incorrect.** Parents preferring the lullaby is an indirect behavioral report and does not directly provide the physiological evidence (reduced heart rate) that the claim relies on.
**Choice D is incorrect.** The singer’s gender does not bear on whether the lullaby produced the physiological effect (lower heart rate) the researchers measured.
**Faster approach:** Match the claim’s stated measure (reduced heart rate = relaxation) to answer choices; pick the choice that directly reports that measure (heart rates lower during lullabies) and eliminate indirect or irrelevant options.'),
  ('fa54db24-c3a3-5948-83a3-efd1ba3ee65d', 0, null, '**Choice A is correct.** The table shows tribal economic activity at \$7,312,400,000, administration/waste at \$5,830,600,000, and real estate at $18,314,700,000.$7,312,400,000 is larger than \$5,830,600,000 (so it surpasses administration/waste) but smaller than \$18,314,700,000 (so it falls short of real estate), which matches the description in choice A.
**Choice B is incorrect.** Tribes did not exceed real estate ($7.31billion <$18.31 billion), so they did not exceed both industries.
**Choice C is incorrect.** Tribes were not greater than real estate and were not equal to administration/waste; the values differ numerically.
**Choice D is incorrect.** Tribes were not lower than both industries because their contribution (\$7.31 billion) is higher than administration/waste (\$5.83 billion).
**Faster approach:** Directly compare the three dollar amounts mentally or by subtracting; identify the middle value to place the tribal contribution relative to the other two industries.'),
  ('89b41fe8-ac43-57f5-b5f7-3b6c4c25161f', 0, null, '**Choice A is correct.** The second team hypothesizes that in low-visibility conditions intermediate-headed fish will be more likely than narrow-headed fish to detect obstructions that create large vortices. Choice A gives a direct comparison in the relevant conditions (large vortices, low visibility): the narrow-headed lake sturgeon bumped into obstructions more often than the intermediate-headed dusky smooth-hound, which implies the intermediate-headed fish detected obstructions more successfully. This directly supports the hypothesis.
**Choice B is incorrect.** Although it reports that a narrow-headed species bumped into many obstructions, it offers no comparison to intermediate-headed fish, so it does not directly support the claim that intermediate-headed fish do better.
**Choice C is incorrect.** Variation among specimens of the intermediate-headed species says nothing about how that species compares to narrow-headed fish and therefore does not directly support the hypothesis.
**Choice D is incorrect.** Saying the intermediate-headed species avoided more than half the obstructions suggests they detected some obstructions, but without data on the narrow-headed species there is no direct comparison to support the hypothesis that intermediates are more likely than narrows to detect obstructions.
**Faster approach:** Look for an answer that directly compares intermediate- and narrow-headed fish under the specified conditions; choose the option that shows which group performed better.'),
  ('bef9bc38-4259-5b95-bd36-f759dec9f1ee', 1, null, '**Choice B is correct.** The graph shows the star line for New York City well above the circle line for Boise for every year 1990–2000, and both lines slope upward: New York rises from about 50 hours to about 66 hours per commuter per year, and Boise rises from roughly 12–15 hours to about 18–20 hours. Thus the Boise value is always lower than New York''s, and congestion (hours of delay) increased in both areas over the period.
**Choice A is incorrect.** Although Boise (and possibly other areas) fell below 20 hours at times, choice A merely states a single low value and does not address the trend of worsening congestion that supports the student’s claim.
**Choice C is incorrect.** Albuquerque’s line (dashed square) is consistently below New York’s line, so it was not greater than New York throughout the period, nor were their values nearly identical in 1996.
**Choice D is incorrect.** In 1992 the New York City value is about 48–50 hours per commuter per year, well above 30 hours.
**Faster approach:** Compare the relative positions and slopes of the lines for the two cities mentioned (large vs. small); checking that one line is always below the other and that both slope upward quickly verifies the claim without reading exact numbers.'),
  ('106524e5-94c8-569f-b3d3-6431a5b21e03', 3, null, '**Choice D is correct.** The table shows rankings (1 = highest). For the general public, "improvement of attitudes and outlooks" has rank 4, while the other four listed services have ranks 8 ("provision of food"), 15 ("provision of raw materials"), 7 ("improvement of physical health"), and 12 ("enhancement of pollination"). Because 4 is a better (lower) rank than 8, 15, 7, and 12, the improvement of attitudes and outlooks is indeed ranked higher by the general public than each of the other four services.
**Choice A is incorrect.** The table shows "improvement of physical health" ranked 5 for project leaders and 7 for the general public, so it is ranked lower (worse) for project leaders than for the general public, not the other way around.
**Choice B is incorrect.** For the general public "provision of raw materials" is ranked 15 and "improvement of attitudes and outlooks" is ranked 4; 15 is a lower (worse) ranking than 4, so provision of raw materials is not ranked higher than improvement of attitudes and outlooks.
**Choice C is incorrect.** Stakeholders ranked "improvement of attitudes and outlooks" as 1, and the general public ranked it as 4; while 1 is higher than 4 for stakeholders, the stem asks for support of the planner’s conclusion that both stakeholders and the general public regard it as important — the correct choice compares the general public’s ranking to the other services, not to stakeholders.
**Faster approach:** Remember that lower numbers = more important. To check any claim about "ranked higher," compare the numeric ranks directly and see which is smaller; this single quick comparison resolves all options.'),
  ('4aaa0bc9-d10f-53ed-a386-60e284277e62', 0, null, '**Choice A is correct.** The paragraph establishes that fruit-eating birds disperse many more seeds from the abundant non-native plants (like night-blooming jessamine) than from vulnerable native plants (like lapalapa) because there are simply more non-native plants for the birds to choose from. Greater seed dispersal of a species is a reasonable basis for expecting a higher rate of population increase for that species; thus it is unsurprising that non-native plants would have a higher rate of population increase than vulnerable native plants.
**Choice B is incorrect.** The passage gives no information about when non-native plants began to outnumber natives, so “only recently began” is unsupported.
**Choice C is incorrect.** The passage says native plants are at risk and that birds disperse fewer native seeds, but it does not say natives already occupy most likely seed-drop spots; that is an unwarranted inference.
**Choice D is incorrect.** The passage contrasts a vulnerable native species with abundant non-native species; it does not state that both named species are the most endangered.
**Faster approach:** Choose the answer that directly follows from the cause–effect in the passage (more seed dispersal → greater potential population growth), eliminating choices that introduce unsupported timing or absolute claims.'),
  ('37e89a1b-8016-5028-8624-7795700aa659', 0, null, '**Choice A is correct.** A semicolon is required to link two closely related independent clauses: "the sculptures ... are meant to challenge viewers to consider their own relationships to material wastes; her thought provoking works ... were no different." The semicolon correctly connects the first clause about the sculptures'' intent with the second clause asserting that her works exhibited in 1993 shared that intent.
**Choice B is incorrect.** "wastes and to" produces an ungrammatical string and disrupts the sentence structure; it does not create a grammatically complete second clause.
**Choice C is incorrect.** A comma would create a comma splice joining two independent clauses without an appropriate coordinating conjunction.
**Choice D is incorrect.** The bare word "wastes" leaves no punctuation to join the following independent clause, making the sentence incomplete or a run-on.
**Faster approach:** When two independent clauses appear back-to-back, look for a semicolon or conjunction; choose the semicolon when no conjunction is present.'),
  ('bb30c107-f5a2-5b06-987a-a38a9aa484b4', 3, null, '**Choice D is correct.** The opening phrase "A recipient of the Othmer Gold Medal and the Davy Medal from the Royal Society," is a modifier that must refer to the grammatical subject that immediately follows it. Choice D begins with "chemist Ahmed Zewail," so the modifier correctly and logically attaches to the person named; the clause that follows describes what he did, making the sentence grammatical and clear.
**Choice A is incorrect.** The subject of the sentence would become "the result," so the opening modifier would incorrectly describe "the result" rather than Ahmed Zewail (a dangling modifier).
**Choice B is incorrect.** The subject would be "the introduction," causing the same dangling-modifier problem: the introductory phrase would not modify the person who received the medals.
**Choice C is incorrect.** The subject would be "the limits of measurability," so the introductory phrase would again be misattached and fail to refer to Ahmed Zewail.
**Faster approach:** After an introductory noun phrase that names a person, choose the answer whose main clause begins with that same person (avoid options that make an abstract noun the subject, which creates a dangling modifier).'),
  ('04d442af-04cd-575e-8a3a-701d8a734a63', 1, null, '**Choice B is correct.** The main subject of the sentence is the singular noun phrase "The Amur River," so it requires a third-person singular present-tense verb. "Flows" agrees with that subject and completes the sentence as a simple present statement about the river’s action: "The Amur River ... flows into the Sea of Okhotsk."
**Choice A is incorrect.** "Flow" is the base (plural) form and does not agree with the singular subject "The Amur River."
**Choice C is incorrect.** "Have flowed" is a present-perfect plural form and also mismatches the singular subject; the correct singular present-perfect would be "has flowed," but that form is unnecessary here.
**Choice D is incorrect.** "Are flowing" is a present-progressive plural form and does not agree with the singular subject; the correct singular progressive would be "is flowing," but the simple present "flows" is the most appropriate tense for this factual statement.
**Faster approach:** Identify the main subject outside any parenthetical clause and use subject-verb agreement—singular subject needs a singular verb ("flows").'),
  ('014bb843-9223-504b-94cf-847ecc5e2ac1', 0, null, '**Choice A is correct.** The sentence needs a declarative continuation that fits the preceding statement and conforms to Standard English punctuation. Choice A, "it was invented by an author." correctly completes the sentence as a statement: "What is the origin of the word “pessimism”? Interestingly, it was invented by an author." The comma after "Interestingly" and the period at the end make this a proper, grammatically complete pair of sentences in which the second sentence presents the informational fact that follows the question.
**Choice B is incorrect.** This option ends with a question mark, producing a second sentence that is a question rather than the intended factual statement; it would create two consecutive questions, which does not match the contrast implied by "Interestingly."
**Choice C is incorrect.** "Wasn’t it invented by an author." is a question tag phrased as a negative question but is punctuated with a period; this mismatch of clause type and punctuation makes it ungrammatical. Even if punctuated as a question, it would still be a follow-up question rather than the straightforward declarative statement called for.
**Choice D is incorrect.** "Was it invented by an author." is also a question (and lacks a question mark here), so it fails for the same reasons as C — it does not provide the clear declarative statement that the context requires.
**Faster approach:** Read the sentence before and after the blank to determine whether the blank should be declarative or interrogative; if the preceding sentence is a question and the following word "Interestingly" signals a factual aside, pick a declarative option with a period.'),
  ('e2cd0333-0723-5aac-beee-e48aa6de0a6f', 3, null, '**Choice D is correct.** The sentence refers to "the judges," a plural noun, so the pronoun that fills the blank must also be plural. "They finally made a decision: the judges for the 1974 Nobel Prize in Literature would award Eyvind Johnson..." maintains clear agreement in number and meaning.
**Choice A is incorrect.** "You" is a second-person pronoun and does not agree with or refer back to the third-person plural noun "the judges."
**Choice B is incorrect.** "It" is singular and would not agree in number with the plural "the judges."
**Choice C is incorrect.** "Anyone" is singular and indefinite; it does not agree with the specific plural noun "the judges," and it would change the sentence’s meaning.
**Faster approach:** Check pronoun-number agreement with the nearest noun (here "the judges" is plural), and choose the plural pronoun "they."'),
  ('e591ea4a-9ec4-535b-a045-73bce48bef6b', 1, null, '**Choice B is correct.** The infinitive "to drive" should continue directly into its object "their cars across France," and the participial phrase "visiting the guide’s recommended hotels and restaurants along the way" modifies that action. Standard English requires no punctuation between the verb and its object here, so the unpunctuated word "drive" is correct.
**Choice A is incorrect.** A period would terminate the sentence at "drive." and leave "their cars across France, visiting..." as a fragment that cannot stand alone.
**Choice C is incorrect.** A colon introduces a list or explanation; what follows is a direct object phrase, not a list or elaboration introduced by a colon.
**Choice D is incorrect.** A semicolon links independent clauses; the words after the blank do not form an independent clause, so a semicolon would be inappropriate.
**Faster approach:** Read the entire sentence; if the words after the blank complete the verb as its object, pick the unpunctuated option. Use punctuation only when the clause truly ends or a list/explanation follows.'),
  ('b350eb2f-2105-51cb-8f7c-694dd91508de', 0, null, '**Choice A is correct.** The sentence uses a noun phrase modified by a participial phrase: "a profile appearing in the Navajo Times on December 12, 2013." The present-participial "appearing" correctly links the noun "profile" to the information about where and when it was published, and it fits the past context established by "was the subject of."
**Choice B is incorrect.** "Appears" is present-tense and cannot grammatically modify "a profile" in this construction.
**Choice C is incorrect.** "Has appeared" (present perfect) conflicts with the simple past context and does not grammatically attach to "a profile" without a relative word.
**Choice D is incorrect.** "Appeared" as a simple past verb cannot directly modify the noun phrase; the sentence would require a relative pronoun ("that appeared").
**Faster approach:** For noun + verb modifiers, choose a participial form ("-ing") when the sentence has "a [noun] [verb-ing]..." rather than a full finite verb; this quickly filters out present or past-finite forms.'),
  ('e6edce32-d100-590e-8bbb-3993fa1c49c2', 2, null, '**Choice C is correct.** The sentence contains a parenthetical phrase set off at the end by an em dash ("—as a novelist"). To balance that dash and clearly mark the intervening parenthetical "especially since her 2020 novel Mexican Gothic reached the New York Times Best Sellers list," an opening em dash after "known" is required: "best known—especially since...—as a novelist." This creates a paired em-dash construction that correctly isolates the explanatory aside.
**Choice A is incorrect.** A bare "known" (no punctuation) leaves the sentence without a marker to set off the parenthetical phrase and produces a choppy reading because only the closing em dash remains.
**Choice B is incorrect.** A colon ("known:") is used to introduce a list or explanation, not to enclose a parenthetical interruption, so it does not pair properly with the closing em dash.
**Choice D is incorrect.** A semicolon ("known;") links two independent clauses and cannot function as the opening element of an em-dash pair; it would create a punctuation mismatch.
**Faster approach:** When you see a closing em dash later in the sentence, insert a matching opening dash (choice with an em dash) to form a balanced parenthetical.'),
  ('da850e80-0f10-57e7-93d5-76abfbc61edb', 1, null, '**Choice B is correct.** The sentence that follows describes a later discovery that occurred "decades later," so a temporal transition that signals a future occurrence fits best. "Eventually" clearly indicates that, after some time, researchers found androsterone in plants, which contrasts with the earlier assumption that it existed only in animals.
**Choice A is incorrect.** "For example" would introduce a specific instance illustrating a prior claim, but the sentence that follows reports a later discovery rather than giving an example of the original point.
**Choice C is incorrect.** "In other words" signals a restatement or clarification of the previous clause; the next sentence is not a restatement but a new, time-shifted fact about later research.
**Choice D is incorrect.** "Earlier" contradicts the time frame in the sentence, which explicitly says the discovery "would" come decades later, so a word indicating prior time is wrong here.
**Faster approach:** Look for time cues (like "decades later") and choose a transition that matches the temporal relationship; here any word signaling a later event (e.g., "eventually") will be correct.'),
  ('bdb45cbd-84bb-569b-9705-9ef07c490ee0', 2, null, '**Choice C is correct.** The sentence contrasts what Chaucer is credited with using (the word “muzzle”) with the fact that he did not write in Modern English; instead he wrote in Middle English. The transition "rather" appropriately signals this corrective contrast: Chaucer didn’t write in Modern English; rather, he wrote in what we now call Middle English.
**Choice A is incorrect.** "As a result" indicates cause and effect, which doesn’t fit because the second clause is not a consequence but a correction/clarification of the first clause.
**Choice B is incorrect.** "Similarly" indicates likeness between two ideas; here the second clause corrects, not compares, so similarity is wrong.
**Choice D is incorrect.** "Finally" suggests a concluding remark or sequence, which is not the intended corrective contrast in this sentence.
**Faster approach:** Look for whether the second clause contrasts or corrects the first; use "rather" for corrections and eliminate options that imply cause, similarity, or sequence.'),
  ('19d6b62a-be74-563b-b44e-f8a40495189b', 0, null, '**Choice A is correct.** The notes for both Thin in the Old and Victor state the media used; each entry lists acrylic among its materials, so this choice accurately emphasizes a clear similarity in medium between the two works.
**Choice B is incorrect.** Although the dates are correctly reported, this sentence merely states chronology rather than highlighting a similarity between the two works.
**Choice C is incorrect.** This choice contrasts the two works by listing their different combinations of media rather than emphasizing how they are similar.
**Choice D is incorrect.** This choice focuses on a size difference (one work is larger) rather than on a similarity; it does not emphasize how the works are alike.
**Faster approach:** Scan the listed facts for a shared detail (a repeated word or phrase such as a medium) and choose the option that states that shared detail.'),
  ('b685a9c3-92b7-5524-a691-b2f759e869b7', 3, null, '**Choice D is correct.** The notes state that minerals with larger Mohs numbers are harder and can leave visible scratches on minerals with smaller numbers; talc is 1 and topaz is 8, so topaz can leave visible scratches on talc, which shows topaz is harder than talc.
**Choice A is incorrect.** Although topaz (8) is harder than fluorite (4) and could scratch it, the choice compares topaz and fluorite rather than directly comparing talc and topaz as the question asks.
**Choice B is incorrect.** The Mohs scale can order those minerals, but the choice merely restates a general capability instead of specifically comparing talc and topaz.
**Choice C is incorrect.** That statement correctly compares fluorite (4) and talc (1) but does not address the required comparison between talc and topaz.
**Faster approach:** Directly compare Mohs numbers: the larger number scratches the smaller, so a mineral with 8 scratches one with 1, proving it is harder.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest May 2023 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('38cf2c1a-6b68-5e19-a985-589740afae65', 'PeaklyTest May 2023 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the May 2023 PeaklyTest · 27 questions · 32 minutes', 32, 361, true, 'PeaklyTest May 2023 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('64d04b83-a92e-52b7-87a5-4bba7f18701e', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text with the most logical and precise word or phrase?', '["recognize", "undermine", "constrain", "establish"]'::jsonb, 1, 'Sarah Marquis, who walked 16,000 kilometers across Asia, Siberia, and Australia, undoubtedly accomplished much, but to _____ a lasting historical legacy for oneself, almost nothing is more effective than being the first to do something. For example, people will always remember that Anesia Pinheiro Machado was the first female pilot in Brazil to carry passengers and the first to make stunt flights.'),
  ('4cb2047f-fe68-5919-9930-c3657fd986a6', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text with the most logical and precise word or phrase?', '["a consequence", "an explanation", "a repudiation", "an objective"]'::jsonb, 2, 'The swordfish can swim very fast—up to 97 kilometers per hour (km/hr)—but it is significantly slower than the frigate bird, which can fly at speeds up to 153 km/hr. The difference between these speeds is largely _____ of the fact that the features that make flight possible do less to limit top speeds than the features suitable for swimming through water.'),
  ('9f5ec5a8-9c54-5a91-9274-54ac7a8955df', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text with the precise word or phrase?', '["reciprocate", "annotate", "abandon", "equalize"]'::jsonb, 3, 'Whether the reign of a French monarch such as Louis VII or Henry V was historically consequential or relatively uneventful, its trajectory was shaped by questions of legitimacy and therefore cannot be understood without a corollary understanding of the characteristics without which the monarch would have been forced to _____ the throne.'),
  ('85dcab89-4a8e-5549-9dbe-9c1230833d7e', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text with the most logical and precise word or phrase?', '["irresolvable", "self-contradictory", "imperative", "unavoidable"]'::jsonb, 4, 'The Caves of Gargas paintings—stencils of human hands found in what is now France and dating from around 27,000 years ago—are thought of as art today, but the question of whether the people of the time understood the paintings as something akin to art in modern sense or in some other way entirely is ______: we will never be able to answer it.'),
  ('dd3b83ad-a6e9-584f-9414-fcb63d0d0174', '38cf2c1a-6b68-5e19-a985-589740afae65', 'As used in the text, what does the word "deep" most nearly mean?', '["Tough", "Hideous", "Complicated", "Intense"]'::jsonb, 5, 'The following text is adapted from William Wordsworth’s 1798 poem "Lines Written a Few Miles above Tintern Abbey.”
Once again
Do I behold these steep and lofty cliffs,
Which on a wild secluded scene impress
Thoughts of more <u>deep</u> seclusion; and connect
The landscape with the quiet of the sky.'),
  ('120e5c84-da35-56fa-bce9-59f1d0cd3b92', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text with the most logical and precise word or phrase?', '["eccentric", "meager", "conventional", "random"]'::jsonb, 6, 'Though many _____ studies of the effect of altitude on blood chemistry focus on people who live above sea level, researchers Suleiman Al-Sweedan and Moath Alhaj recently chose the novel path of focusing on people who live below sea level, in locations such as the California towns of Salton City and Coachella.'),
  ('3576640c-2c67-5018-9a54-d9de7fe6215b', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Based on the texts, how would Lorde (Text 1) most likely respond to the argument presented in Text 2?', '["By indicating that those poets who publish in major poetry journals are most likely to be able to earn a living by writing poetry.", "By pointing out that people can produce valuable poetry in other circumstances than those described by the author of Text 2.", "By suggesting that those artists who specialize in more financially rewarding artistic forms are unlikely to also be successful as poets.", "By asserting that people often work full-time jobs in order to afford the professional training described in Text 2."]'::jsonb, 7, '**Text 1**

The poet Audre Lorde once claimed that poetry is the most inexpensive of art forms to practice. While people who pursue other art forms—sculpture, architecture, long-form prose—require large blocks of uninterrupted time as well as money to complete their work, poets can write, as Lorde said, "between shifts, in the hospital pantry, on the subway, and on scraps of surplus paper." So poets can make worthwhile art even if they must earn their living in another way.

**Text 2**

Any assessment of the state of contemporary poetry must reckon with the professionalization of the field. While it is possible in theory for anyone to publish in Virginia Quarterly Review, Kenyon Review, or a similar major poetry outlet, many people who do so have professional training in poetry and extensive practice writing it, which requires time not often available to those who must also work full-time jobs. Thus, financial security indirectly affects which people become poets.'),
  ('dbda7522-fe14-500f-86d6-68d29dfce77f', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice best states the main idea of the text?', '["Over time, the Aubrey/Maturin series has acquired the same eminence among critics as works like In Search of Lost Time that have similar structures.", "A certain understanding of the structures of the novels in the Aubrey/Maturin series is helpful if one wishes to appreciate the series.", "Many readers find the Aubrey/Maturin novels to be remarkably entertaining despite flaws in the novels'' structures.", "The Yellow Admiral and The Hundred Days are two of the most complex of O''Brian’s novels due in part to their unconventional structures."]'::jsonb, 8, 'The Yellow Admiral, first published in 1996, is a novel in Patrick O''Brian’s Aubrey/Maturin series, which includes twenty books plus an unfinished fragment of a twenty-first. Like the rest of the books in the series, The Yellow Admiral has a rather abrupt ending, but the following book, The Hundred Days, picks up neatly where The Yellow Admiral leaves off. Thus, the sudden ending is only an issue if one considers the books as independent texts—the Aubrey/Maturin series is best thought of as a single incredibly long work, similar to other multivolume stories, such as Marcel Proust’s In Search of Lost Time.'),
  ('f6d75cca-7cac-5d25-8cff-443b88b6aee6', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice best describes the main idea of the text?', '["Victor became disappointed in science when he realized that the practical knowledge laypeople have of nature is often deeper than the scientific understanding.", "Victor was impressed by the layperson’s practical understanding of nature but thought science provided a clearer understanding.", "Victor was immediately impressed by the advantages of the scientific approach to understanding natural phenomena.", "Victor thinks that conventional scientific approaches to understanding natural phenomena will not yield the answers he seeks."]'::jsonb, 9, 'The following text is from Mary Shelley’s 1818 novel Frankenstein. Victor Frankenstein, who narrates this portion of text, describes the state of scientific knowledge as he began his own study of the natural world.

The untaught peasant beheld the elements around him and was acquainted with their practical uses. The most learned philosopher knew little more. He had partially unveiled the face of Nature, but her immortal lineaments were still a wonder and a mystery. He might dissect, anatomize, and give names; but, not to speak of a final cause, causes in their secondary and tertiary grades were utterly unknown to him. I had gazed upon the fortifications and impediments that seemed to keep human beings from entering the citadel of nature, and rashly and ignorantly I had repined.'),
  ('cd1e18e7-2d89-5be6-8773-25f858a8c383', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice most effectively uses data from the table to complete the statement?', '["A) Agaricia undata, because its minimum depth of 20 meters is in the shallow zone.", "B) Plerogyra discus, because its maximum depth of 15 meters is furthest from the mesophotic zone.", "C) Acropora echinata, because its maximum depth of 25 meters is close to but doesn’t reach the mesophotic zone.", "D) Psammocora albopicta, because its minimum depth of 1 meter is the shallowest of those listed."]'::jsonb, 10, '**Minimum and Maximum Depths of Stony Coral Species in Caribbean and Indo-Pacific Waters**

| Species | Minimum depth (meters) | Maximum depth (meters) |
| Plerogyra discus | 8 | 15 |
| Acropora echinata | 8 | 25 |
| Psammocora albopicta | 1 | 28 |
| Agaricia undata | 20 | 80 |

Some scientists have suggested that as ocean temperatures rise, many fish and corals found in the shallow zone (less than 30 meters below the surface) could take refuge in the cooler, darker mesophotic zone (30 to 150 meters below the surface). However, it isn’t clear that all such species will be able to tolerate mesophotic conditions. In 2018, Luiz Rocha and colleagues studied stony corals in the two zones in Caribbean and Indo-Pacific waters. Based on the depths at which those corals are now found, the species that seems least suited to a full migration to the mesophotic zone is _____'),
  ('cacda5cd-44c6-5d11-85b7-b53bc10bf20e', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice most logically completes the text?', '["if a cultural movement has both literary and nonliterary innovations, then it is likely to be influential.", "if a cultural movement is very innovative, then it is unlikely to be able to sustain itself for long.", "if literary works of a cultural movement are influential, then it doesn’t matter whether the unliterary works are.", "if the influence of a cultural movement continues, then in some sense the movement itself continues."]'::jsonb, 11, 'The Harlem Renaissance, which gave us great literary works like May Miller’s play The Bog Guide and nonliterary works like James Van DerZee’s photograph Couple, Harlem, is often said to have ended in the 1930s shortly after the Great Depression began. But some scholars argue that the Harlem Renaissance never really ended because it continues to shape culture in the United States today. These scholars therefore suggest that _____'),
  ('1e5bc064-9f82-5c5a-8165-20043ba25d00', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice most logically completes the text?', '["serves to exaggerate the building’s historical importance.", "fails to convey the full impact of the building’s design and structure.", "misrepresents how the building is perceived by people who have never visited Beijing.", "conceals the subtle deterioration of the building’s materials."]'::jsonb, 12, 'Architects looking for inspiration may examine photographs of iconic buildings such as the Forbidden City in Beijing. A two-dimensional photograph, however, cannot capture how a building interacts with its surroundings, whether by complementing, blending in with, or perhaps even clashing with sights and activities nearby. An image of the Forbidden City thus ______'),
  ('2881d442-e149-5aa0-a362-e23b901556bc', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice most logically completes the text?', '["marketing studies are not likely to require data from very many individuals.", "data from 25,000 people may not be enough to reveal significant trends in economic well-being.", "long-term trends in economic well-being are hard to find without collecting data over many years.", "long-term trends in marketing can be found without examining many years of data."]'::jsonb, 13, 'Some studies can be done well with relatively little money. For example, a marketing study simply trying to identify the average amount customers spend per transaction at an online retailer has a straightforward central question that doesn’t require many years of data collection. But it is much more expensive to conduct a longitudinal study like the Household, Income and Labour Dynamics in Australia Survey (HILDA), which looks at data for 25,000 people in Australia to find trends in economic well-being that can take a long time to develop. This requires lots of funding because _____'),
  ('b0c4b91a-b992-5168-b0d3-abf11601ae63', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which finding, if true, would most directly weaken the hypothesis presented in the text?', '["When D. polymorpha and O. mykiss are exposed to similar levels of CeO2-NPs, concentrations of CeO2-NPs in animals of both species show little variation from individual to individual.", "The rate of CeO2-NPs uptake in D. polymorpha differs from the rate of CeO2-NPs uptake in O. mykiss in a way that is not yet well understood by researchers.", "D. polymorpha has been shown to accumulate several other types of manufactured nanoparticles in addition to CeO2-NPs, whereas O. mykiss has been shown to accumulate only CeO2-NPs.", "Compared with O. mykiss, D. polymorpha can accumulate detectable CeO2-NPs concentrations with significantly fewer negative effects."]'::jsonb, 14, 'Some fuel additives contain cerium oxide nanoparticles (CeO2-NPs), which can leach into waterways and soils via wastewater. In a 2015 study, Mael Garaud and colleagues found that CeO2-NPs can accumulate in the bodies of zebra mussels (Dreissena polymorpha). While bioaccumulation of manufactured nanoparticles may be inherently worrisome, it has been hypothesized that CeO2-NP bioaccumulation in invertebrates like D. polymorpha could serve a valuable proxy role, obviating the need for manufacturers to conduct costly and intrusive sampling of vertebrate species such as rainbow trout (Oncorhynchus mykiss), commonly used in regulatory compliance testing for manipulative bioaccumulation, as environmental protection laws currently require.'),
  ('72061eba-ab23-53f8-be72-ce208be9c6c7', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice most logically completes the text?', '["The number of people going to gas stations at restaurants is greater than that of people going to gas stations near schools.", "People who go to gas stations at restaurants have higher expectations about the service because of higher price.", "People are more willing to give good comments to gas stations near schools.", "More gas stations should be established near schools."]'::jsonb, 15, 'Generally speaking, whether consumers give a good comment or a bad one is closely related to their expectations about the kind of service they will get. Some gas stations are located near schools while others are near restaurants. People who go to gas stations near schools usually get discounts for refueling their automobiles. However, such discounts are not provided at gas stations near restaurants. Recent studies show that the rate of good comments versus bad comments made to the gas stations near cafeteria is lower than the rate near schools, suggesting that _____'),
  ('155a2dcd-8053-5ddd-94e0-ae521ce6411e', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice most logically completes the text?', '["the new skin-care product is less appealing to parents of small children than other similar products on the market are.", "there is not a meaningful difference in the average likelihood of purchasing environmentally friendly products among the demographic groups included in the study.", "parents of small children likely prioritize other factors over a product’s environmental sustainability when making purchasing decisions.", "parents of small children might be more likely than participants in the other demographic groups to purchase the skin-care product."]'::jsonb, 16, 'Saeed M. Z. A. Tarabieh conducted a study of consumer attitudes toward Jordanian food and beverage companies and found that for consumers who value environmental conservation, their likelihood of purchasing a product decreased when their perception of the product’s risk of causing environmental harm increased. Subsequently, other researchers conducted a study of various demographic groups in Turkey, investigating participants'' intentions to purchase a new skincare product, and found that, on average, parents of small children had the lowest perception among all the demographic groups in the study of the environmental risks of the skin-care product. Assuming that the results of Tarabieh’s study are broadly applicable, this finding suggests that _____'),
  ('2a014a73-4511-583e-bb93-22cfcc5360a7', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["were", "have been", "are", "was"]'::jsonb, 17, 'During the American Civil War, Thomas Morris Chester braved the front lines as a war correspondent for the Philadelphia Press. Amplifying the voices and experiences of Black soldiers _____ of particular importance to Chester, who later became an activist and lawyer during the postwar Reconstruction period.'),
  ('82289b90-edd2-5868-908d-851e47ada42b', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["players, before", "players and before", "players. Before", "players before"]'::jsonb, 18, 'The first multi-player computer video game, Steve Russell’s Spacewar!, challenged games'' abilities not only to maneuver their spaceships but also to decide how best to utilize their limited weaponry so that they could defeat other Spacewar!’s _____ development, playing a video game was a more solitary experience in which one game player tried to beat a single computer.'),
  ('ac91d214-7eca-5dfb-93a7-f9af052b2927', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["webs, however,", "webs however", "webs, however;", "webs; however,"]'::jsonb, 19, 'To most observers, it might seem like the net-casting spider’s small web consists of the same silk spun by other arachnids that make larger, fixed _____ the net casting spider uses a unique, stretchy silk to construct a net between its front legs that has more elasticity, enabling the net to expand tremendously when the spider lunges to capture prey. Biologist Jessica Garb and her research team hypothesize that this superior stretchiness comes from proteins in its silk.'),
  ('c436fd57-cd55-5830-bc32-d7eec91fafa3', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["to protect", "protected", "and protecting", "protecting"]'::jsonb, 20, 'Advancing a previous discovery by K. Barry Sharpless, chemist Carolyn Bertozzi—winner of the 2022 Nobel Prize in Chemistry alongside Sharpless and Morten Meldal—devised a method for the removal of toxic byproducts from click chemistry _____ healthy cells in humans for use in a variety of pharmaceutical treatments.'),
  ('f687927c-e21c-5d96-8486-d4cd8ae7db86', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["stressed", "stressed,", "stressed;", "stressed:"]'::jsonb, 21, 'According to Maria Magdalena Llabre of the University of Miami, the reason that the rate of heart disease seems lower in US Hispanics than in their non-Hispanic white counterparts while similarly _____ is that the nature of the Spanish language better supports emotional expression, helping its speakers manage their stress responses.'),
  ('b956502c-7408-556d-934d-2789458f912c', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["follows", "are following", "have followed", "follow"]'::jsonb, 22, 'The modern board game backgammon has its roots in the earliest identifiable tables game from the Byzantine Empire, tabula. In both games, the rules are the same for hitting a blot (landing on an occupied point) and bearing off (removing checkers from the board); re-entering one of the checkers into the game also _____ the same rules in backgammon as in tabula.'),
  ('2624f6ee-f874-5353-a76e-de3a3367c9eb', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text with the most logical transition?', '["In reality,", "Nevertheless,", "Hence,", "Next,"]'::jsonb, 23, 'The moon Leda orbits Jupiter in the same direction that the planet rotates. _____ Leda’s orbit is described as prograde. Ananke, another of Jupiter’s moons, orbits in the opposite direction, so its orbit is described with the opposite term: retrograde.'),
  ('83e99279-5ab0-5b16-8781-08b41d98e6dc', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text with the most logical transition?', '["In other words,", "As a result,", "Still,", "For example,"]'::jsonb, 24, 'As part of a study, participants were asked to list animals they thought of as “charismatic,” which was defined as “attractive, fascinating, or appealing.” Researchers compiled the responses into a single list and found that the cheetah and the blue whale both landed in the top twenty. _____ no animal outranked the tiger.'),
  ('4a28ae21-7b86-54e1-afa6-8823e844b217', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text with the most logical transition?', '["Conversely,", "Specifically,", "Finally,", "Nevertheless,"]'::jsonb, 25, 'Shonte Tucker has worked at NASA’s famed Jet Propulsion Laboratory (JPL), one of the world’s leading facilities for robotic space exploration. _____ Tucker worked as a systems engineer on the JPL’s Mars 2020 Perseverance rover team, which improved upon the 2011 Curiosity rover design by adding a coring drill to the robot that could collect rock samples for later analysis.'),
  ('f6f5ee03-ff08-57f0-9993-a25e539ee00b', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["physicist Mishkat Bhattacharya,", "physicist, Mishkat Bhattacharya", "physicist Mishkat Bhattacharya", "physicist, Mishkat Bhattacharya,"]'::jsonb, 26, 'Superconductors, materials that transmit electricity without any resistance to the flow of the electric current, only work at extremely low temperatures. In a 2023 article, _____ asserts that researchers have made progress toward developing superconductors that can function at room temperature and still carry up to five times as much electricity as current cables.'),
  ('3a27fd08-e925-5691-bc11-9c9d5684f42b', '38cf2c1a-6b68-5e19-a985-589740afae65', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["these penguins could become extinct.", "these penguins could become extinct?", "could these penguins become extinct.", "could these penguins become extinct?"]'::jsonb, 27, 'Stephanie Jenouvrier of the Woods Hole Oceanographic Institution asserts that when climate change results in sea ice abatement, emperor penguin chicks encounter fewer solid surfaces for required respite when they are not swimming, which increases their chance of drowning and thus endangers this species. If elevated temperatures continue, _____ Jenouvrier conducted a study to find the answer.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('64d04b83-a92e-52b7-87a5-4bba7f18701e', 3, null, '**Choice D is correct.** The verb "establish" collocates naturally with "a lasting historical legacy," so the sentence reads logically: to establish a lasting historical legacy for oneself, almost nothing is more effective than being the first to do something. The meaning matches the preceding clause about noteworthy accomplishments and the example of being first in a national context.
**Choice A is incorrect.** "Recognize a lasting historical legacy for oneself" would mean to notice or acknowledge such a legacy, but the sentence requires an active verb meaning to create or secure a legacy, not merely to perceive it.
**Choice B is incorrect.** "Undermine" has the opposite meaning (weaken or damage) and contradicts the claim that being first is effective at producing a legacy.
**Choice C is incorrect.** "Constrain" means to limit; it does not fit the intended sense of producing or securing a lasting legacy.
**Faster approach:** Look for collocations—pairings like "establish a legacy" are common and immediately signal the correct choice.'),
  ('4cb2047f-fe68-5919-9930-c3657fd986a6', 0, null, '**Choice A is correct.** The sentence says the speed difference exists because of a particular fact about flight versus swimming; saying it is "a consequence of the fact that..." precisely expresses that causal relationship. The noun "consequence" with the preposition "of" correctly links the difference to its cause.
**Choice B is incorrect.** "An explanation of the fact that" would mean the difference explains the fact, which reverses the intended causal relationship; the passage intends the fact to explain the speed difference, not the other way around.
**Choice C is incorrect.** "A repudiation of the fact that" would mean the difference rejects the fact, which makes no sense in context because the sentence is presenting the fact as the reason for the difference.
**Choice D is incorrect.** "An objective of the fact that" is illogical: a fact cannot have an "objective" that explains a measured difference in speeds, and the phrase does not convey the causal link required.
**Faster approach:** Substitute each option into the sentence and check which yields a natural causal phrase; only "a consequence of" produces the intended cause‑effect meaning.'),
  ('9f5ec5a8-9c54-5a91-9274-54ac7a8955df', 2, null, '**Choice C is correct.** The sentence says a monarch’s reign "cannot be understood without a corollary understanding of the characteristics without which the monarch would have been forced to _____ the throne." The context requires a verb meaning to give up possession or control of the throne; "abandon" precisely conveys yielding or relinquishing a reign, so it completes the idea logically and grammatically.
**Choice A is incorrect.** "Reciprocate" means to return a gesture or action; it does not fit the sense of leaving or giving up the throne.
**Choice B is incorrect.** "Annotate" means to add notes to a text; it is unrelated to the concept of a monarch leaving power.
**Choice D is incorrect.** "Equalize" means to make equal; it does not express the idea of relinquishing or leaving the throne and therefore is not appropriate in this context.
**Faster approach:** Look for the verb meaning "give up" or "leave" in the context of yielding power; eliminate choices with unrelated meanings to select the appropriate word quickly.'),
  ('85dcab89-4a8e-5549-9dbe-9c1230833d7e', 0, null, '**Choice A is correct.** The sentence says that because of limitations in evidence or perspective, we "will never be able to answer" whether the Paleolithic people saw the paintings as art in our sense; thus the question is one that cannot be resolved. "Irresolvable" precisely conveys that meaning.
**Choice B is incorrect.** "Self-contradictory" would mean the question contradicts itself, which is not implied; the passage indicates a lack of answerability, not a contradiction in the question.
**Choice C is incorrect.** "Imperative" means urgent or necessary, which conflicts with the following clause that the question cannot be answered.
**Choice D is incorrect.** "Unavoidable" means unavoidable or inevitable; it does not fit the idea that the question cannot be answered.
**Faster approach:** Substitute each option into the sentence and read aloud; the choice that preserves logical sense with "we will never be able to answer it" is the correct one (here, "irresolvable").'),
  ('dd3b83ad-a6e9-584f-9414-fcb63d0d0174', 3, null, '**Choice D is correct.** In the phrase "deep seclusion," "deep" modifies the noun "seclusion" to intensify it; the poet means a serious, intense sense of being secluded. "Deep" here conveys a strong or profound quality, so "intense" is the best match.
**Choice A is incorrect.** "Tough" suggests difficulty or hardness, which does not fit the poet’s description of the quality of seclusion.
**Choice B is incorrect.** "Hideous" means ugly or horrifying; the context describes quiet, secluded cliffs, not something frightening or ugly.
**Choice C is incorrect.** "Complicated" suggests complexity or intricacy; the passage emphasizes the degree of seclusion, not that the seclusion is complex.
**Faster approach:** Substitute each answer into the phrase "deep seclusion" and choose the one that preserves the meaning ("intense seclusion" fits best), a quick context-based synonym check that works for vocabulary-in-context questions.'),
  ('120e5c84-da35-56fa-bce9-59f1d0cd3b92', 2, null, '**Choice C is correct.** The sentence contrasts the typical focus of prior studies with the researchers'' "novel path" of studying people below sea level. The word "conventional" precisely denotes what is usual or customary, so "many conventional studies... focus on people who live above sea level" sets up the contrast with the new, atypical approach described.
**Choice A is incorrect.** "Eccentric" means odd or unconventional; it would conflict with the idea that the researchers'' choice is "novel," since the sentence needs a word describing the common, not the unusual.
**Choice B is incorrect.** "Meager" means scant or insufficient; that sense doesn’t fit the context, which discusses the typical focus of prior studies rather than their quantity or quality.
**Choice D is incorrect.** "Random" implies lack of pattern or intent and does not create the clear contrast with a "novel" deliberate research choice that "conventional" provides.
**Faster approach:** Look for contrast words (here, "novel") and choose the option that denotes the opposite (here, "conventional").'),
  ('3576640c-2c67-5018-9a54-d9de7fe6215b', 1, null, '**Choice B is correct.** Text 1 emphasizes that poetry is inexpensive to practice and that poets can write "between shifts, in the hospital pantry, on the subway, and on scraps of surplus paper," allowing them to produce worthwhile art even while holding other jobs. That directly challenges Text 2’s implication that only those with professional training and time can become poets by asserting that valuable poetry can be produced in less privileged circumstances.
**Choice A is incorrect.** Lorde’s claim highlights the opposite point: she argues that poets need not earn a living by writing or have large blocks of time to create important work, so she would not emphasize journal-published poets as likely to earn a living from poetry.
**Choice C is incorrect.** Text 1 does not make a claim about artists in other fields being unlikely to be poets; it only stresses poetry’s accessibility to those who must work other jobs.
**Choice D is incorrect.** Lorde’s focus is that poetry can be produced without extensive time or money, not that people take full-time jobs to afford professional training; she argues the opposite—that valuable poetry can come from those who must work.
**Faster approach:** Look for the author’s main claim in Text 1 (poetry is accessible and can be written amid work) and choose the answer that directly contradicts Text 2’s emphasis on professional training/time constraints.'),
  ('dbda7522-fe14-500f-86d6-68d29dfce77f', 1, null, '**Choice B is correct.** The passage argues that the abrupt ending of The Yellow Admiral only poses a problem if readers treat each volume as an independent work and that the Aubrey/Maturin books are best understood as a single, continuous multivolume work; therefore, recognizing the series’ overall structure is important for appreciating it. The final sentence explicitly states this claim and supports it by analogy to other multivolume works such as In Search of Lost Time.
**Choice A is incorrect.** The passage mentions a similarity in structure to Proust’s work but does not claim the series has achieved the same critical eminence.
**Choice C is incorrect.** The passage does not discuss readers’ enjoyment or entertainment value of the novels.
**Choice D is incorrect.** The passage does not assert that those two novels are the most complex or that complexity is due to unconventional structure.
**Faster approach:** Read the final sentence(s) for the author’s explicit claim—authors often state the main idea directly in the passage’s conclusion.'),
  ('f6d75cca-7cac-5d25-8cff-443b88b6aee6', 3, null, '**Choice D is correct.** The passage describes conventional science as uncovering only surface features —“partially unveiled the face of Nature,” able to “dissect, anatomize, and give names,” while deeper causes remain “utterly unknown.” Victor says these methods leave “fortifications and impediments” that keep humans “from entering the citadel of nature,” signaling his conviction that usual scientific approaches will not reveal the ultimate answers he seeks.
**Choice A is incorrect.** While the passage notes the peasant’s practical knowledge, Victor does not claim lay understanding is deeper than scientific knowledge; he emphasizes that both have limits, with science knowing more superficially (“partially unveiled”) but still missing deeper causes.
**Choice B is incorrect.** The passage does show Victor noting the peasant’s acquaintance with practical uses, but it does not say science provides a clearer understanding; instead it stresses science’s failure to reach final causes, so “clearer understanding” misstates his view.
**Choice C is incorrect.** Victor is not “immediately impressed by the advantages” of science; he criticizes science’s limitations and complains of “fortifications and impediments” that keep humans from true understanding, so the choice contradicts the skeptical tone.
**Faster approach:** Scan the passage for evaluative words about science (e.g., “utterly unknown,” “fortifications,” “repined”); those words reveal whether the narrator endorses or rejects conventional scientific methods—use that judgment to eliminate choices that portray science as successful or superior.'),
  ('cd1e18e7-2d89-5be6-8773-25f858a8c383', 1, null, '**Choice B is correct.** The mesophotic zone begins at 30 meters, so a species whose recorded maximum depth is farthest from 30 m is least likely, based on current depth data, to already occupy or tolerate mesophotic conditions. Plerogyra discus has a maximum depth of 15 m, which is 15 meters shallower than the mesophotic threshold and is the shallower maximum of the species listed, so it appears least suited to a full migration into the 30–150 m zone.
**Choice A is incorrect.** Agaricia undata’s minimum depth is 20 m, but its maximum depth is 80 m, indicating it already occurs well within the mesophotic zone, so it is not the least suited.
**Choice C is incorrect.** Acropora echinata’s maximum depth is 25 m, which is close to the mesophotic threshold, but Plerogyra’s maximum (15 m) is farther from 30 m, making Plerogyra a better answer.
**Choice D is incorrect.** Psammocora albopicta has a minimum depth of 1 m but a maximum depth of 28 m, which is very close to 30 m; therefore it is more likely than Plerogyra to be able to reach mesophotic depths.
**Faster approach:** Compare each species’ maximum depth to 30 m; the species with the smallest maximum depth (farthest below 30 m) is least likely to occupy the mesophotic zone.'),
  ('cacda5cd-44c6-5d11-85b7-b53bc10bf20e', 3, null, '**Choice D is correct.** The passage says some scholars argue the Harlem Renaissance "never really ended because it continues to shape culture in the United States today." That reasoning equates continued influence with continued existence of the movement, which is exactly what choice D states: if the influence continues, then the movement continues in some sense.
**Choice A is incorrect.** The passage notes both literary and nonliterary works, but it does not claim that having both kinds of innovations guarantees broad influence; that is an unsupported generalization.
**Choice B is incorrect.** The passage mentions the Renaissance is often said to have ended in the 1930s, but it does not claim that high innovativeness makes a movement unable to sustain itself.
**Choice C is incorrect.** The passage does not suggest that the influence of literary works makes nonliterary influence irrelevant; rather, it focuses on overall continuing influence as evidence the movement persists.
**Faster approach:** Look for an answer that restates the passage’s logical link (continued influence = continued existence); eliminate choices that introduce new, unsupported claims.'),
  ('1e5bc064-9f82-5c5a-8165-20043ba25d00', 1, null, '**Choice B is correct.** The passage states that a two-dimensional photograph "cannot capture how a building interacts with its surroundings," so an image of the Forbidden City would not convey the full impact of the building’s design and structure in context. This directly matches the idea in choice B that the photograph "fails to convey the full impact."
**Choice A is incorrect.** The passage discusses limitation in conveying interaction with surroundings, not exaggerating historical importance; nothing supports exaggeration.
**Choice C is incorrect.** The passage does not address people’s perceptions or misrepresentation to those who have never visited Beijing; it addresses loss of contextual information, not perception errors.
**Choice D is incorrect.** The text says nothing about material deterioration or concealment of damage; it focuses on loss of contextual interaction, not physical condition.
**Faster approach:** Focus on the specific limitation stated in the sentence before the blank (what the photograph "cannot capture") and choose the answer that restates that limitation in different words.'),
  ('2881d442-e149-5aa0-a362-e23b901556bc', 2, null, '**Choice C is correct.** The passage contrasts a simple marketing study that does not need many years of data with the expensive HILDA longitudinal study that follows 25,000 people to find trends that "can take a long time to develop." The most logical completion is that lots of funding is required because long-term trends in economic well-being are hard to find without collecting data over many years, which is exactly what choice C states.
**Choice A is incorrect.** Though the passage implies a marketing study can be small, A does not explain why the HILDA study requires lots of funding; it shifts focus to marketing rather than the reason for expense.
**Choice B is incorrect.** The passage presents 25,000 participants as part of a large, expensive study; B contradicts that implication by suggesting 25,000 may be insufficient and does not address the need for long-term data collection.
**Choice D is incorrect.** D is irrelevant and contradicts the passage’s contrast; the passage says long-term economic trends require many years, so saying long-term marketing trends can be found without many years does not explain the funding need.
**Faster approach:** Spot the contrast marker ("but") and match the clause after "because" to the passage’s stated reason (that trends "take a long time to develop"); pick the choice that restates that reason directly.'),
  ('b0c4b91a-b992-5168-b0d3-abf11601ae63', 1, null, '**Choice B is correct.** The hypothesis depends on zebra mussel uptake reflecting trout uptake so mussels can stand in for trout. If the rates of CeO2-NP uptake differ between D. polymorpha and O. mykiss in an unexplained way, that undermines the assumption that mussel bioaccumulation reliably predicts trout bioaccumulation; the lack of understanding weakens the proxy idea directly.
**Choice A is incorrect.** If both species show similar, low individual variation in CeO2-NP concentrations when exposed similarly, that supports using mussels as a proxy, not weakens it.
**Choice C is incorrect.** Differences in the range of nanoparticles each species accumulates does not directly show that mussel CeO2-NP levels fail to predict trout CeO2-NP levels; it’s indirect and not as directly undermining as B.
**Choice D is incorrect.** That mussels suffer fewer negative effects at detectable concentrations addresses toxicity, not whether mussel bioaccumulation levels correspond to trout bioaccumulation, so it doesn’t most directly weaken the proxy hypothesis.
**Faster approach:** Look for the answer that shows a fundamental mismatch or unknown relationship in uptake between the two species — any statement that calls into question comparability of accumulation directly weakens a proxy claim.'),
  ('72061eba-ab23-53f8-be72-ce208be9c6c7', 1, null, '**Choice B is correct.** The passage links consumers'' comments to their expectations and notes that stations near schools offer discounts while those near restaurants do not; it also reports that the rate of good comments is lower near cafeterias (restaurants) than near schools. The best inference is that patrons of restaurant-area stations have higher expectations about service—perhaps because they pay more there—so they are likelier to give negative comments when expectations aren’t met. Choice B directly explains the observed lower rate of good comments by invoking higher expectations due to higher prices, which follows from the passage’s premise-relating expectations, discounts, and comment rates.
**Choice A is incorrect.** The number of people visiting stations is not mentioned and cannot explain the lower rate of good comments; the passage concerns expectations and discounts, not traffic volume.
**Choice C is incorrect.** While stations near schools do have a higher rate of good comments, the passage explains this difference in terms of expectations and discounts, not greater willingness to praise; choice C restates the observation rather than offering the causal inference supported by the text.
**Choice D is incorrect.** The passage provides no basis for recommending where to build more stations; suggesting more stations near schools is an unrelated policy prescription not supported by the given evidence.
**Faster approach:** Identify the causal link the passage sets up (comments depend on expectations) and look for the answer that explains the observed difference in comment rates by referencing expectations—eliminate choices that introduce unrelated facts (visitor counts, construction recommendations) or merely restate the observation.'),
  ('155a2dcd-8053-5ddd-94e0-ae521ce6411e', 3, null, '**Choice D is correct.** Tarabieh’s finding states that for consumers who value environmental conservation, an increased perception of a product’s environmental risk reduces their likelihood of purchasing it. The Turkish study reports that parents of small children have the lowest perception of the product’s environmental risks. Combining these two facts: lower perceived risk should correspond to a higher likelihood of purchase, so parents of small children might be more likely than other groups to buy the product.
**Choice A is incorrect.** It directly contradicts the logical implication of lower perceived risk leading to higher likelihood of purchase for conservation-minded consumers.
**Choice B is incorrect.** The passage gives a specific relation between perceived risk and purchase likelihood, so it does not support a claim of no meaningful difference among groups.
**Choice C is incorrect.** Nothing in the passage indicates that parents of small children prioritize other factors; the passage only reports their lower perception of environmental risk.
**Faster approach:** Link the two given facts directly—map "higher perceived risk → lower purchase likelihood" to "group with lowest perceived risk → relatively higher purchase likelihood." This yields the correct choice immediately.'),
  ('2a014a73-4511-583e-bb93-22cfcc5360a7', 3, null, '**Choice D is correct.** The subject of the sentence is the gerund phrase "Amplifying the voices and experiences of Black soldiers," which is singular and takes a singular verb. "Was" is the singular past-tense verb that correctly agrees with that subject and matches the past-tense context established by the rest of the sentence ("Chester... later became").
**Choice A is incorrect.** "Were" is a plural past-tense verb; it does not agree with the singular gerund subject "Amplifying..." and so creates a subject-verb agreement error.
**Choice B is incorrect.** "Have been" is a perfect present construction requiring a plural subject (or I/we/you), and it also conflicts with the past-tense context of the sentence, making it ungrammatical here.
**Choice C is incorrect.** "Are" is present-tense plural and therefore mismatches both the singular gerund subject and the past-tense timeframe implied by the clause about Chester’s later career.
**Faster approach:** Identify the grammatical subject (here a singular gerund phrase) and match it with a singular verb in the correct tense—because the sentence is set in the past, choose the past singular "was."'),
  ('82289b90-edd2-5868-908d-851e47ada42b', 2, null, '**Choice C is correct.** The sentence requires a full stop after "players" to separate two independent ideas. Ending the sentence with "players." allows the next sentence to begin with "Before development," which correctly modifies the clause "playing a video game was a more solitary experience..." The period fixes the run-on and clarifies the time contrast between early single-player experience and later multiplayer developments.
**Choice A is incorrect.** Inserting a comma ("players, before") produces a comma splice and leaves the second clause grammatically dependent and unclear.
**Choice B is incorrect.** "players and before" creates an ungrammatical connector; the conjunction "and" does not appropriately join these clauses or permit the transitional temporal phrase that follows.
**Choice D is incorrect.** "players before" strings the phrases together without proper punctuation, producing a fused sentence that fails to mark the independent clause boundary.
**Faster approach:** For sentence-boundary problems, check whether the material after the choice can stand alone as an independent clause; if so, use a period (or semicolon) to separate—this quickly eliminates comma or conjunction choices.'),
  ('ac91d214-7eca-5dfb-93a7-f9af052b2927', 3, null, '**Choice D is correct.** The sentence joins two independent clauses: "other arachnids that make larger, fixed webs" (implied clause) and "the net-casting spider uses a unique, stretchy silk..." When connecting independent clauses with the conjunctive adverb "however," standard punctuation requires a semicolon before "however" and a comma after it. "webs; however," provides that correct punctuation and creates a grammatically correct, smooth contrast.
**Choice A is incorrect.** "webs, however," inserts only a comma, which creates a comma splice because it does not properly separate the two independent clauses.
**Choice B is incorrect.** "webs however" lacks any necessary commas or semicolon; it fails to mark the contrast and incorrectly joins two independent clauses without proper punctuation.
**Choice C is incorrect.** "webs, however;" places the semicolon after "however," which is the wrong order; the semicolon must come before "however" when linking independent clauses.
**Faster approach:** When you see "however" joining two clauses, treat it as a conjunctive adverb and use a semicolon before it and a comma after it to join two independent clauses.'),
  ('c436fd57-cd55-5830-bc32-d7eec91fafa3', 0, null, '**Choice A is correct.** The infinitive phrase "to protect healthy cells" expresses the purpose of devising the method: she devised a method for removing toxic byproducts in order to protect healthy cells. That purpose relationship fits the sentence and conforms to Standard English.
**Choice B is incorrect.** "Protected" is a past participle; "removal of toxic byproducts from click chemistry protected healthy cells" is ungrammatical and fails to show the intended purpose.
**Choice C is incorrect.** "And protecting" would create a faulty coordination with "removal": "a method for the removal ... and protecting" is not parallel and makes the sentence awkward and unclear.
**Choice D is incorrect.** While "protecting healthy cells" (a participial phrase) could sometimes work, it is less clear than the infinitive for expressing purpose here; the infinitive "to protect" more directly indicates why the method was devised.
**Faster approach:** For phrases that express purpose following verbs like "devised a method," choose the infinitive form ("to ...") because it most clearly indicates intention or purpose.'),
  ('f687927c-e21c-5d96-8486-d4cd8ae7db86', 0, null, '**Choice A is correct.** The sentence pairs two adjectives in a parallel comparison ("lower in US Hispanics than in their non-Hispanic white counterparts") and needs the adjective "stressed" without additional punctuation to complete the clause "while similarly stressed." Adding nothing preserves the grammatical parallelism and creates a clear subordinate clause modifying "counterparts."
**Choice B is incorrect.** A comma after "stressed" creates an unnecessary break and leaves the subordinate clause hanging; the comma implies a following independent clause or parenthetical element, which does not occur here.
**Choice C is incorrect.** A semicolon cannot join the subordinate phrase to the main clause; semicolons connect two independent clauses, but "while similarly stressed" is not independent.
**Choice D is incorrect.** A colon should introduce a list, explanation, or quotation that follows, but nothing follows here to be introduced; therefore a colon is inappropriate.
**Faster approach:** For filling a short adjectival clause after "while," read the sentence aloud with each punctuation option; if the phrase flows naturally and completes the comparison without needing a pause or an independent clause after it, choose the plain adjective with no added punctuation.'),
  ('b956502c-7408-556d-934d-2789458f912c', 0, null, '**Choice A is correct.** The subject of the clause is the gerund phrase "re-entering one of the checkers into the game," which is singular, so it requires a singular present-tense verb. "Follows" is the singular present form that agrees with that subject and correctly completes the sentence: "re-entering ... also follows the same rules."
**Choice B is incorrect.** "Are following" is a plural progressive form that does not agree with the singular gerund subject and is awkward in this context.
**Choice C is incorrect.** "Have followed" is a present-perfect plural form that conflicts with the singular gerund subject and changes the intended simple-present meaning.
**Choice D is incorrect.** "Follow" is the plural present form; it does not agree with the singular gerund subject and so is ungrammatical here.
**Faster approach:** Identify the subject (a gerund phrase = singular) and choose the singular present tense (add -s): "follows."'),
  ('2624f6ee-f874-5353-a76e-de3a3367c9eb', 2, null, '**Choice C is correct.** The second sentence states a logical conclusion about Leda’s orbit based on the fact that it orbits in the same direction as Jupiter’s rotation, so a causal transition such as "Hence" (meaning "therefore") appropriately signals that the second sentence follows from the first.
**Choice A is incorrect.** "In reality" suggests a contrast between appearance and fact, but the passage presents no contrast; it gives a straightforward causal explanation, so this transition is inappropriate.
**Choice B is incorrect.** "Nevertheless" indicates a concession or contrast, which does not match the relationship between the two sentences; there is no opposing idea to concede.
**Choice D is incorrect.** "Next" signals sequence or chronology, but the second sentence is an explanation or consequence, not the next step in a sequence, so it is not the best transition.
**Faster approach:** For short explanatory pairs, choose a cause-and-effect transition ("therefore/hence/so") whenever the second sentence states a conclusion that follows from the first; eliminate words that indicate contrast or sequence.'),
  ('83e99279-5ab0-5b16-8781-08b41d98e6dc', 2, null, '**Choice C is correct.** The sentence before the blank lists examples (the cheetah and the blue whale) and the next clause contrasts those examples with the tiger’s rank: although those animals were in the top twenty, none outranked the tiger. The transition "Still," signals that contrast and continuity, making the sentence logically coherent.
**Choice A is incorrect.** "In other words," would restate or clarify the previous idea, but the following clause presents contrasting information rather than a rephrasing.
**Choice B is incorrect.** "As a result," indicates a causal relationship; the sentence does not claim that the earlier examples caused the tiger’s ranking.
**Choice D is incorrect.** "For example," would introduce an illustration, but the clause that follows gives a contrasting statement about the tiger, not an example.
**Faster approach:** Identify whether the next clause contrasts, restates, gives a cause, or offers an example; then pick the transition that matches that logical relation (contrast → "Still"/"However").'),
  ('4a28ae21-7b86-54e1-afa6-8823e844b217', 1, null, '**Choice B is correct.** The sentence before the blank introduces Shonte Tucker’s affiliation with JPL, and the following clause gives a specific example of her work. "Specifically," signals that the writer is narrowing from the general statement to a particular detail: that Tucker worked as a systems engineer on the Perseverance rover team and contributed to a design improvement.
**Choice A is incorrect.** "Conversely" indicates a contrast or opposite idea, but the second clause does not present a contrast with the first; it gives a concrete example.
**Choice C is incorrect.** "Finally" implies a concluding point in a sequence, which the context does not support —the sentence provides additional information, not a final summary.
**Choice D is incorrect.** "Nevertheless" also signals contrast or concession; again, the second clause does not contradict or qualify the first, so this transition is inappropriate.
**Faster approach:** For transitions that introduce a specific example or detail after a general statement, pick "Specifically"; eliminate options that signal contrast or conclusion.'),
  ('f6f5ee03-ff08-57f0-9993-a25e539ee00b', 2, null, '**Choice C is correct.** The phrase functions as a simple subject noun phrase naming who makes the assertion: "physicist Mishkat Bhattacharya asserts..." No commas are needed because "physicist Mishkat Bhattacharya" is an essential title+name combination that directly precedes the verb.
**Choice A is incorrect.** The comma after "Mishkat Bhattacharya" would create an unnecessary pause before the verb ("Mishkat Bhattacharya, asserts"), which is ungrammatical here.
**Choice B is incorrect.** The comma between "physicist" and the name incorrectly separates the title from the person it identifies, and omits a needed comma after the name if an appositive structure were intended.
**Choice D is incorrect.** Commas before and after the name would set off an appositive, but the order is wrong; the correct appositive form would place the name first ("Mishkat Bhattacharya, a physicist, asserts").
**Faster approach:** When a title immediately precedes a proper name and acts as an essential identifier, choose the version without commas; reserve commas for nonessential appositives that can be removed without changing the core meaning.'),
  ('3a27fd08-e925-5691-bc11-9c9d5684f42b', 3, null, '**Choice D is correct.** The sentence introduces a direct question about the future possibility, so the clause must be in interrogative form with subject–auxiliary inversion and end with a question mark: "Could these penguins become extinct?" This fits with the following clause, "Jenouvrier conducted a study to find the answer," which explains why the question is raised.
**Choice A is incorrect.** "these penguins could become extinct." is a declarative clause; it lacks subject–auxiliary inversion and a question mark, so it does not form the direct question implied by the context.
**Choice B is incorrect.** Although it has a question mark, the word order is declarative (no inversion), so it is not properly formed as a direct question in Standard English.
**Choice C is incorrect.** "could these penguins become extinct." has correct word order for a question but ends with a period instead of a question mark, which is punctuationally incorrect for a direct question.
**Faster approach:** For any sentence that clearly poses a question, use subject–auxiliary inversion and a question mark; if the wording is inverted but ends with a period, change the punctuation to a question mark (and vice versa).')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;
